package io.atlas.modules.pokedex.repository;
import io.atlas.modules.database.DatabaseManager;
import java.util.*;
public final class TypeRouteRepository {
 public record Progress(String type,int milestone,int caught,int total,java.time.Instant completed,boolean selected){}
 public List<Progress> load(UUID id){var out=new ArrayList<Progress>();try(var p=DatabaseManager.getConnection().prepareStatement("SELECT * FROM pokedex_type_progress WHERE uuid=? ORDER BY type")){p.setObject(1,id);try(var r=p.executeQuery()){while(r.next())out.add(new Progress(r.getString("type"),r.getInt("milestone"),r.getInt("caught"),r.getInt("total"),r.getTimestamp("completed_at")==null?null:r.getTimestamp("completed_at").toInstant(),r.getBoolean("selected")));}return out;}catch(java.sql.SQLException e){throw new IllegalStateException(e);}}
 public void save(UUID id,String type,int milestone,int caught,int total){try(var p=DatabaseManager.getConnection().prepareStatement("INSERT INTO pokedex_type_progress(uuid,type,milestone,caught,total,completed_at) VALUES(?,?,?,?,?,CASE WHEN ?=100 THEN now() ELSE NULL END) ON CONFLICT(uuid,type) DO UPDATE SET milestone=GREATEST(pokedex_type_progress.milestone,EXCLUDED.milestone),caught=EXCLUDED.caught,total=EXCLUDED.total,completed_at=COALESCE(pokedex_type_progress.completed_at,EXCLUDED.completed_at)")){p.setObject(1,id);p.setString(2,type);p.setInt(3,milestone);p.setInt(4,caught);p.setInt(5,total);p.setInt(6,milestone);p.executeUpdate();}catch(java.sql.SQLException e){throw new IllegalStateException(e);}}
 public boolean select(UUID id,String type){var c=DatabaseManager.getConnection();try{c.setAutoCommit(false);try(var p=c.prepareStatement("SELECT uuid FROM players WHERE uuid=? FOR UPDATE")){p.setObject(1,id);p.executeQuery().close();}try(var p=c.prepareStatement("UPDATE pokedex_type_progress SET selected=FALSE WHERE uuid=?")){p.setObject(1,id);p.executeUpdate();}int changed;try(var p=c.prepareStatement("UPDATE pokedex_type_progress SET selected=TRUE WHERE uuid=? AND type=? AND completed_at IS NOT NULL")){p.setObject(1,id);p.setString(2,type);changed=p.executeUpdate();}if(changed==1)c.commit();else c.rollback();return changed==1;}catch(java.sql.SQLException e){try{c.rollback();}catch(Exception ignored){}throw new IllegalStateException(e);}finally{try{c.setAutoCommit(true);}catch(Exception ignored){}}}
}
